<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { api, unwrapPage } from './services/api'
import { ElButton, ElButtonGroup, ElDialog, ElEmpty, ElForm, ElFormItem, ElInput, ElOption, ElSelect, ElTable, ElTableColumn, ElTag } from 'element-plus'

type LibraryRow = { id: string; title: string; type: string; lifecycle: string; owner: string; updated: string; favorite: boolean }
const actorId = String(import.meta.env.VITE_ACTOR_ID || ''); const query = ref(''); const typeFilter = ref('全部'); const lifecycleFilter = ref('全部'); const loading = ref(false); const dialog = ref(false); const title = ref(''); const resourceType = ref('电影'); const toast = ref('')
const rows = ref<LibraryRow[]>([])
const types = ['全部', '电影', '文档', '集合', '音乐', '文章']; const lifecycles = ['全部', '正常', '已归档', '回收站']
const filteredRows = computed(() => rows.value.filter(row => (!query.value || `${row.title} ${row.type} ${row.owner}`.toLowerCase().includes(query.value.toLowerCase())) && (typeFilter.value === '全部' || row.type === typeFilter.value) && (lifecycleFilter.value === '全部' || row.lifecycle === lifecycleFilter.value)))
function notify(message: string) { toast.value = message; window.setTimeout(() => toast.value = '', 2400) }
async function load() { loading.value = true; try { const result = unwrapPage(await api.listResources('?limit=50')); rows.value = result.map(item => ({ id: item.id, title: item.title || item.id.slice(0, 8), type: item.resource_type || '其他', lifecycle: item.lifecycle || '正常', owner: '当前用户', updated: item.updated_at ? new Date(item.updated_at).toLocaleString('zh-CN') : '刚刚', favorite: false })) } catch { notify('资源库加载失败，请检查登录状态或后端服务') } finally { loading.value = false } }
async function create() { if (!title.value.trim()) { notify('请输入资源标题'); return } if (!actorId) { notify('未配置当前用户身份，无法创建资源'); return } try { const item = await api.createResource({ title: title.value.trim(), resource_type: resourceType.value, owner_id: actorId }); rows.value.unshift({ id: item.id, title: item.title || title.value.trim(), type: item.resource_type || resourceType.value, lifecycle: item.lifecycle || '正常', owner: '当前用户', updated: '刚刚', favorite: false }); dialog.value = false; title.value = ''; notify('资源已创建') } catch (error) { notify(error instanceof Error ? error.message : '资源创建失败') } }
async function toggleFavorite(row: LibraryRow) { if (!actorId) { notify('未配置当前用户身份，无法修改收藏'); return } const next = !row.favorite; try { if (next) await api.addFavorite(row.id, actorId); else await api.removeFavorite(row.id, actorId); row.favorite = next; notify(next ? '已加入收藏' : '已取消收藏') } catch { notify('收藏状态更新失败，请稍后重试') } }
async function syncFavorites() { if (!actorId) return; await Promise.all(rows.value.filter(row => !row.id.startsWith('demo-')).map(async row => { try { const result = await api.getFavorite(row.id, actorId); row.favorite = Boolean(result.favorite ?? result.favorited) } catch { /* 单条收藏不可用时保留默认状态 */ } })) }
onMounted(async () => { await load(); await syncFavorites() })
</script>

<template><div class="library-shell"><header class="catalog-topbar"><div class="catalog-brand"><span class="brand-mark">i</span><strong>Ikaros <small>Console</small></strong></div><span class="catalog-context">内容与创作 · 本地环境</span><span class="mini-avatar">陈</span></header><main class="library-main"><div class="catalog-heading"><div><p class="eyebrow">内容与创作</p><h1>统一资源库</h1><p>Resource 表示逻辑内容，而不是物理存储位置。</p></div><div class="library-actions"><el-button @click="notify('导入流程即将打开')">⇩ 导入</el-button><el-button type="primary" @click="dialog = true">＋ 创建资源</el-button></div></div><div class="library-kpis"><div class="mini-kpi"><span>资源总数</span><b>{{ rows.length }}</b><small>当前授权范围</small></div><div class="mini-kpi"><span>正常可用</span><b class="success-text">{{ rows.filter(row => row.lifecycle === '正常').length }}</b><small>可正常使用</small></div><div class="mini-kpi"><span>已归档</span><b>{{ rows.filter(row => row.lifecycle === '已归档').length }}</b><small>仍可恢复</small></div><div class="mini-kpi"><span>元数据冲突</span><b class="warning-text">0</b><small>需要关注</small></div></div><section class="library-toolbar surface-card"><el-input v-model="query" clearable placeholder="搜索资源标题、别名或 ID" style="max-width:360px" /><el-select v-model="lifecycleFilter" style="width:140px"><el-option v-for="value in lifecycles" :key="value" :label="value" :value="value" /></el-select><el-button-group><el-button v-for="value in types" :key="value" :type="typeFilter === value ? 'primary' : 'default'" @click="typeFilter = value">{{ value }}</el-button></el-button-group></section><section class="library-table surface-card"><el-table v-loading="loading" :data="filteredRows" stripe empty-text="没有匹配资源，请调整筛选条件。"><el-table-column prop="title" label="资源" min-width="220"><template #default="{ row }"><RouterLink :to="`/console/resources/${row.id}`" class="library-name"><b>{{ row.title }}</b></RouterLink></template></el-table-column><el-table-column prop="type" label="类型" width="110"><template #default="{ row }"><el-tag type="info">{{ row.type }}</el-tag></template></el-table-column><el-table-column prop="lifecycle" label="生命周期" width="120"><template #default="{ row }"><el-tag :type="row.lifecycle === '正常' ? 'success' : 'warning'">{{ row.lifecycle }}</el-tag></template></el-table-column><el-table-column prop="owner" label="所有者" width="120" /><el-table-column prop="updated" label="最近更新" width="170" /><el-table-column label="收藏" width="90"><template #default="{ row }"><el-button link :type="row.favorite ? 'warning' : 'info'" @click="toggleFavorite(row)">{{ row.favorite ? '★' : '☆' }}</el-button></template></el-table-column><el-table-column label="操作" width="90"><template #default="{ row }"><RouterLink :to="`/console/resources/${row.id}`"><el-button link type="primary">查看</el-button></RouterLink></template></el-table-column></el-table><div class="table-footer"><span>显示 {{ filteredRows.length }} 项，共 {{ rows.length }} 项</span><el-button link :loading="loading" @click="load">刷新</el-button></div></section></main><el-dialog v-model="dialog" title="创建资源" width="460px"><el-form label-position="top" @submit.prevent="create"><el-form-item label="标题"><el-input v-model="title" autofocus placeholder="输入资源标题" /></el-form-item><el-form-item label="类型"><el-select v-model="resourceType" style="width:100%"><el-option v-for="value in types.slice(1)" :key="value" :label="value" :value="value" /></el-select></el-form-item><p class="account-note">创建后 Resource 类型默认不可直接修改；后续可在详情页添加附件与外部身份。</p><div class="dialog-actions"><el-button @click="dialog = false">取消</el-button><el-button type="primary" @click="create">创建资源</el-button></div></el-form></el-dialog><el-empty v-if="false" description="暂无资源" /><div v-if="toast" class="snackbar">✓ {{ toast }}<button @click="toast = ''">×</button></div></div></template>
